pub struct Buf {
    bytes: Vec<u8>,
}

impl Buf {
    pub fn as_words(&self) -> Vec<u32> {
        self.bytes
            .chunks(4)
            .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }
}

