pub struct Buf {
    bytes: Vec<u8>,
}

impl Buf {
    pub fn as_words(&self) -> Vec<u32> {
        let ptr = self.bytes.as_ptr() as *const u32;
        unsafe { std::slice::from_raw_parts(ptr, self.bytes.len() / 4).to_vec() }
    }
}
